    var request = new TestRequest(scenario.id, rng.NextInt(1, 247), rng.NextInt(3, 4), address, rng.NextInt(1, Math.Min(125, 65536 - address)), rng.Pick(new[] { 1, 0.1, 0.01, 1000000, 1e-9 }));
    c.Input = request.ToString();
